mapper.update:

 		 	UPDATE TBL_RFQ_ATTRI_VERIFY /*updateQuotationReq*/ 
 		 		SET GW_NO = #{GW_NO}			
			WHERE BUYER = #{st_buyer2}				
			AND RAV_NO = #{st_rav_no}


 		 	UPDATE TBL_RFQ_ATTRI_VERIFY /*updateQuotationReqEndFlag*/ 
 		 		SET STATUS = 'E'			
			WHERE BUYER = #{st_buyer2}				
			AND RAV_NO = #{st_rav_no}


 		 	UPDATE TBL_RFQ_ATTRI_VERIFY     /*updateNgRequest*/
		       SET STATUS = 'E'		
			WHERE BUYER = #{KEY_2}
		      AND GW_NO = #{KEY_1}


 		 	UPDATE KEPRQDT    /*updateNgApproval*/
		       SET RECV_FLAG = 'NW'
			    WHERE BUYER = #{KEY_2}
		      AND GW_GA_NO = #{KEY_1}  
		      AND STATUS IN ('C','R')
		      AND RECV_FLAG != 'GR'


 		 	UPDATE KEPRQDT    /*updateNgReject*/
		       SET RECV_FLAG = 'GR'
			    WHERE BUYER = #{KEY_2}
		      AND GW_GA_NO = #{KEY_1}  
		      AND STATUS IN ('C','R')


 		 	UPDATE KEPRQDT    /*updateNgReject_v2*/
		       SET RECV_FLAG = 'NR'
			    WHERE BUYER = #{KEY_2}
		      AND GW_GA_NO = #{KEY_1}  
		      AND STATUS IN ('C','R')


 		 	UPDATE TBL_RFQ_ATTRI_VERIFY /*delReqQuotation*/ 
 		 		SET STATUS = 'D' 				
				,KEP_REMARK = KEP_REMARK ||' DELETE(USER : '||#{userid}||', DATE : ' || TO_CHAR(SYSDATE,'YYYY/MM/DD HH24:MI:SS')|| ')'
			WHERE BUYER = #{st_buyer2}				
			AND RAV_NO = #{st_rav_no}
